func sort(_ a: [Int]) async -> [Int] {
    if a.count < 1024 { return a.sorted() }                  // base case
    let mid = a.count / 2
    return await withTaskGroup(of: [Int].self) { group in
        group.addTask { await sort(Array(a[..<mid])) }
        group.addTask { await sort(Array(a[mid...])) }
        var halves: [[Int]] = []
        for await half in group { halves.append(half) }      // join
        return merge(halves[0], halves[1])                   // combine
    }
}

